from lib import *
S = SS('c36')
steps = [
    step("Docker Desktop 虚拟机有 MemTotal 8124516 kB、SwapTotal 1048572 kB(约 1 GiB 的 swap)。容器里读 cgroup:不限制 → memory.max=max、memory.swap.max=max;--memory 64m → memory.max=67108864、memory.swap.max=67108864(只给内存时,swap 也被限在 64 MiB);--memory 64m --memory-swap 64m → swap.max=0;--memory 64m --memory-swap 128m → swap.max=67108864(--memory-swap 是内存加 swap 的总和,128m 减 64m 剩 64m swap);--memory 64m --memory-swap -1 → swap.max=max。", t=tl(S(1)), done=lidx(S(1), '不限制:', '--memory 64m:'), mark=lidx(S(1), '--memory-swap 64m:', '--memory-swap 128m:', '--memory-swap -1:'), kv=KV([['--memory 64m', 'memory.max 64 MiB,swap.max 64 MiB'], ['--memory-swap 64m', 'swap.max = 0'], ['--memory-swap 128m', 'swap.max = 64 MiB(总和 128m 减内存)'], ['--memory-swap -1', 'swap.max = max']], ['--memory-swap 128m'])),
    step("在容器里每次 10 MiB、真正写入地一直分配到 200 MiB:不限制 → 分配完 200 MiB,ExitCode 0;--memory 64m → 分配到 110 MiB 时(memory.current=54 MiB、swap.current=61 MiB)被杀,ExitCode=137、OOMKilled=True;--memory 64m --memory-swap 64m(不允许 swap)→ 只到 50 MiB 就被杀;--memory-swap 128m → 110 MiB;--memory-swap -1(swap 不限)→ memory.current=54 MiB、swap.current=151 MiB,200 MiB 全部分配完,ExitCode=0。进程数据多出来的部分被换出到 swap。", t=tl(S(2)), done=lidx(S(2), '不限制:', '--memory-swap -1'), mark=lidx(S(2), '--memory 64m:', '--memory-swap 64m:', '--memory-swap 128m:'), b=bars([['不限制 (MiB)', 200, '200'], ['--memory 64m (MiB)', 110, '110'], ['--memory-swap 64m (MiB)', 50, '50'], ['--memory-swap 128m (MiB)', 110, '110'], ['--memory-swap -1 (MiB)', 200, '200']], 200, done=[0, 4], mark=[1, 2, 3]), kv=KV([['不允许 swap', '50 MiB 被杀'], ['允许 64 MiB swap', '110 MiB 被杀(54 内存 + 约 60 swap)'], ['swap 不限', '200 MiB 完成,151 MiB 在 swap']], ['允许 64 MiB swap'])),
    step("--memory-reservation 32m(软限制)配合 --memory 64m:cgroup 里 memory.max=67108864,memory.low=33554432,memory.high=max;docker stats 显示 552KiB / 64MiB,LIMIT 是硬上限 64MiB,不是 reservation。", t=tl(S(3)), done=lidx(S(3), 'memory.high / memory.low'), mark=lidx(S(3), 'docker stats'), kv=KV([['memory.max', '64 MiB(--memory)'], ['memory.low', '32 MiB(--memory-reservation)'], ['docker stats 的 LIMIT', '64MiB']], ['memory.low'])),
]
A = mkartc('c36', 36, 'Docker,cgroup,内存限制,memory-swap,swap,OOM,真实验证,动画演示',
    '在 Docker Engine 29.8.2(cgroup v2)里实测 --memory 与 --memory-swap:只给 --memory 64m 时 swap 也被限在 64 MiB(memory.swap.max=67108864),--memory-swap 是内存加 swap 的总和;分配 200 MiB 时,不允许 swap 的容器在 50 MiB 被杀,允许 64 MiB swap 的在 110 MiB 被杀,swap 不限的 200 MiB 全部分配完(151 MiB 在 swap 里);--memory-reservation 对应 memory.low。',
    '--memory 和 --memory-swap 的数字怎么算?容器内存超了是被杀,还是被换到 swap?这篇把几种组合翻译成 cgroup 文件里的值,并用逐步分配内存的程序看每种设置下的实际表现。',
    [('50 / 110 / 200 MiB', '--memory 64m 下 swap 为 0 / 64 MiB / 不限时,程序能分配到的内存量(前两个被 OOM 杀死)'), ('swap.max = 内存+swap 总和 − 内存', '--memory-swap 128m 配 --memory 64m 得到的 memory.swap.max = 64 MiB'), ('151 MiB 在 swap', '--memory-swap -1 时分配 200 MiB,memory.current 只有 54 MiB')],
    [('cgroup 里的值', '<p>虚拟机有约 1 GiB swap。<code>--memory 64m</code> 单独使用时,swap 也被限制在 64 MiB(<code>memory.swap.max</code> = 67108864);<code>--memory-swap</code> 表示内存加 swap 的总和,所以 128m 配 64m 内存,swap 只有 64 MiB;<code>--memory-swap 64m</code> 则完全不允许 swap(0);<code>-1</code> 不限。</p>'),
     ('超限的表现', '<p>分配 200 MiB:不允许 swap 的容器在 50 MiB 附近就被杀(137,OOMKilled=true);允许 64 MiB swap 的撑到 110 MiB(约 54 MiB 在内存、60 MiB 左右在 swap);swap 不限的把 200 MiB 都分配了,其中 151 MiB 被换到 swap,容器没被杀——代价是换页的开销,我没有测速度。</p>'),
     ('软限制', '<p><code>--memory-reservation</code> 对应 <code>memory.low</code>(32 MiB),<code>docker stats</code> 的 LIMIT 仍是 <code>--memory</code> 的 64MiB。memory.low 在内存紧张时才起作用,怎么起作用我没有实验。</p>')],
    steps,
    [ENV_C + '。虚拟机 MemTotal 8124516 kB、SwapTotal 1048572 kB;测试程序是 python:3.12-alpine 里的脚本,每次分配并写入 10 MiB(os.urandom),输出时读 /sys/fs/cgroup/memory.current 与 memory.swap.current;每种情形运行一次;实验后已删除容器和镜像',
     '没有验证:swap 的读写速度与性能影响、memory.high 的节流、cgroup v1 的行为、Linux 宿主机没有开 swap 或 swapaccount 时的表现、--oom-kill-disable(见后面的 OOM 一篇)'],
    '内存限制与 swap')
